INSERT INTO query_cache (id, question_hash, question, persona_id, client_id, component, sql_query, viz_type, is_known_component, query_fn, suggested_chips, capability, cached_at, hit_count, ai_message) VALUES ('06c6ca67-fa7e-4872-94b8-cf3d5256a8f8', '8a9078133af5a47bb7702db7ad4fb976', 'Show me safety exposure by unit', 'complex-manager', 'aramco', 'Table', 'SELECT z.id,z.name,z.hazard_level,COUNT(DISTINCT w.id) AS workers,COUNT(DISTINCT p.id) AS active_permits,COUNT(DISTINCT CASE WHEN p.risk_bucket IN (''''safety'''',''''health'''') THEN p.id END) AS high_risk_permits,COUNT(DISTINCT fj.id) AS flagged_jobs FROM zone z LEFT JOIN worker w ON w.zone_id=z.id LEFT JOIN permit p ON p.zone_id=z.id AND p.status=''''valid'''' LEFT JOIN flagged_job fj ON fj.zone_id=z.id GROUP BY z.id,z.name,z.hazard_level ORDER BY flagged_jobs DESC,high_risk_permits DESC', 'Table', FALSE, NULL, '["What is the schedule versus safety trade-off?", "Why are the headcounts disagreeing?", "What would I tell the board''s safety committee today?"]', 'Proactive Intelligence', '2026-09-10T19:18:35.104170-04:00', 6, NULL);
